from modele import chapitre,E,Q,tableau
from pedagogie import page,sec,bloc

chapitre(13,'distances-cercles','Droites, distances et cercles','3 · Espace et géométrie',
'Notations · Distance · Milieu · Cercle et disque',
['Employer un vocabulaire précis et coder les propriétés utiles.','Utiliser la distance entre deux points et le milieu d’un segment.','Caractériser cercle et disque par une distance au centre.'],
['Règle, équerre et compas ; perpendicularité et parallélisme.'],[
page(1,'Objets, notations et positions de droites',
bloc('definition',r'Par deux points A et B passe une seule droite, notée (AB). Le segment [AB] est la partie de cette droite comprise entre A et B ; la demi-droite [AB) commence en A et passe par B. La longueur du segment [AB] se note AB, sans crochets.'),
r'@FIG:cours-objets@',
bloc('propriete',r'Deux droites perpendiculaires se coupent en formant un angle droit ; deux droites parallèles ne se coupent pas. On code un angle droit par un petit carré et des longueurs égales par un même signe.'),
sec(2,'Distance et milieu d’un segment'),
bloc('definition',r'La distance entre deux points A et B est la longueur AB du segment [AB]. Le milieu du segment [AB] est le point M de ce segment tel que $AM=MB$ ; alors $AM=MB=AB:2$.'),
bloc('savoirfaire',r'Pour placer le milieu d’un segment de 7 cm, on place sur le segment le point situé à $7:2=3{,}5$ cm de l’une des extrémités, puis on code les deux moitiés.','Placer un milieu')),
page(3,'Cercle, disque et éléments associés',
bloc('definition',r'Le cercle de centre O et de rayon $r$ est formé de tous les points situés à la distance $r$ du point O. Le disque de centre O et de rayon $r$ est formé de tous les points dont la distance à O est inférieure ou égale à $r$ : c’est le cercle et son intérieur.'),
r'@FIG:cours-cercle@',
bloc('definition',r'Un rayon joint le centre à un point du cercle. Une corde joint deux points du cercle ; une corde qui passe par le centre est un diamètre. Un diamètre mesure deux rayons.'),
sec(4,'Décrire des conditions de distance'),
bloc('savoirfaire',r'Pour situer un point M par rapport au cercle de centre O et de rayon 3 cm, on compare OM à 3 cm : si $OM=3$ cm, M est sur le cercle ; si $OM<3$ cm, M est à l’intérieur du cercle ; si $OM>3$ cm, M est à l’extérieur.','Comparer à un rayon'),
bloc('exemple',r'Les points situés à 2 cm de A et à 3 cm de B sont à la fois sur le cercle de centre A de rayon 2 cm et sur le cercle de centre B de rayon 3 cm : ce sont leurs points d’intersection.')),
],[
E('Nommer les objets',r'Nommer chacun des trois objets tracés avec la bonne notation.',r'Objet 1 : la $\res{\text{droite (AB)}}$, illimitée des deux côtés. Objet 2 : le $\res{\text{segment [CD]}}$. Objet 3 : la $\res{\text{demi-droite [EF)}}$, qui commence en E et passe par F.','Regarder si le tracé s’arrête à un point, à deux points ou pas du tout.','assert 3==len(["droite","segment","demi-droite"])',figure='dis-1'),
E('Lire les codages',r'Écrire toutes les informations données par les codages du quadrilatère ABCD.',r'Un trait : $\res{AB=AD}$. Deux traits : $\res{CB=CD}$. Le petit carré indique un angle droit en A : les droites (AB) et (AD) sont $\res{\text{perpendiculaires}}$.','Associer chaque signe à une égalité.','assert 2+1==3',figure='dis-2'),
E('Le milieu',r'Le segment [AB] mesure 7 cm et M est son milieu. Calculer AM. Le point N du segment [AB], placé à 3 cm de A, est-il le milieu de [AB] ?',r'$AM=7:2=\res{3{,}5\ \mathrm{cm}}$. Pour N : $AN=3$ cm et $NB=7-3=4$ cm. Comme $AN\ne NB$, N n’est $\res{\text{pas le milieu}}$.','Le milieu partage le segment en deux longueurs égales.','assert Rational(7,2)==Rational("3.5") and 7-3!=3',figure='dis-3'),
E('Vocabulaire du cercle',r'Pour chaque segment tracé, dire s’il s’agit d’un rayon, d’un diamètre ou d’une corde.',r'[OA] : un $\res{\text{rayon}}$. [BC] : un $\res{\text{diamètre}}$, qui est aussi une corde passant par O. [DE] : une $\res{\text{corde}}$.','Repérer si le segment passe par le centre.','assert 2*1==2',figure='dis-4'),
E('Sur le cercle ou non ?',r'Le cercle a pour centre O et pour rayon 3 cm. On sait que $OM=3$ cm, $ON=2{,}4$ cm et $OP=3{,}6$ cm. Situer M, N et P par rapport au cercle.',r'M est $\res{\text{sur le cercle}}$. N est $\res{\text{à l’intérieur}}$ : il appartient au disque. P est $\res{\text{à l’extérieur}}$.','Comparer chaque distance au rayon.','assert Rational("2.4")<3<Rational("3.6")',figure='dis-5'),
E('Rayon et diamètre',r'Le cercle $\mathcal C_1$ a pour diamètre $4{,}6$ cm et le cercle $\mathcal C_2$ a pour rayon $1{,}4$ cm. Calculer le rayon de $\mathcal C_1$ et le diamètre de $\mathcal C_2$. Lequel est le plus grand cercle ?',r'Rayon de $\mathcal C_1$ : $4{,}6:2=\res{2{,}3\ \mathrm{cm}}$. Diamètre de $\mathcal C_2$ : $2\times1{,}4=\res{2{,}8\ \mathrm{cm}}$. Le plus grand est $\res{\mathcal C_1}$.','Un diamètre vaut deux rayons.','assert Rational("4.6")/2==Rational("2.3") and 2*Rational("1.4")==Rational("2.8") and Rational("2.3")>Rational("1.4")',figure='dis-6'),
E('À égale distance',r'Les points A et B sont tels que $AB=4$ cm. Construire tous les points situés à 2 cm de A et à 3 cm de B. Combien y en a-t-il ?',r'On trace le cercle de centre A de rayon 2 cm et le cercle de centre B de rayon 3 cm. Ils se coupent en $\res2$ points, en vert, symétriques par rapport à la droite (AB).','Chaque condition de distance correspond à un cercle.','assert 3-2<4<2+3',figure='dis-7'),
E('Un cercle de diamètre donné',r'Le segment [AB] mesure 6 cm. Placer son milieu M, puis tracer le cercle de diamètre [AB]. Quel est son rayon ?',r'M est à 3 cm de A. Le cercle a pour centre M et pour rayon $\res{3\ \mathrm{cm}}$ ; il passe par A et par B (en vert).','Le centre d’un cercle de diamètre [AB] est le milieu de [AB].','assert 6/2==3',figure='dis-8'),
E('La corde la plus longue',r'Dans le cercle de centre O et de rayon $2{,}5$ cm, trois cordes sont tracées. Laquelle est la plus longue ? Peut-on tracer une corde de 6 cm dans ce cercle ?',r'La plus longue est $\res{\text{[AB]}}$ : elle passe par O, c’est un diamètre de 5 cm. Aucune corde ne dépasse un diamètre : une corde de 6 cm est $\res{\text{impossible}}$.','Un diamètre est la plus longue des cordes.','assert 2*Rational("2.5")==5 and 6>5',figure='dis-9'),
E('Comparer au compas',r'Sans règle graduée, ranger les segments [AB], [CD] et [EF] du plus court au plus long, à l’aide du compas.',r'On prend l’écartement de [CD] au compas et on le reporte sur les autres segments. On obtient : $\res{CD<AB<EF}$ ; en mesurant ensuite : $3{,}4$ cm, $3{,}6$ cm et $3{,}8$ cm.','Le compas compare deux longueurs sans les mesurer.','assert Rational("3.4")<Rational("3.6")<Rational("3.8")',figure='dis-10'),
E('L’antenne',r'Sur la carte, 1 cm représente 1 km. Une antenne A capte les téléphones jusqu’à 3 km. Quels villages sont couverts ? Les distances à l’antenne sont : V1 $2{,}1$ km ; V2 $3{,}4$ km ; V3 $2{,}9$ km ; V4 3 km.',r'La zone couverte est le disque de centre A et de rayon 3 km, en vert. Sont couverts $\res{\text{V1, V3 et V4}}$ ; V4 est exactement sur le cercle. V2 n’est pas couvert.','Comparer chaque distance au rayon.','d=[Rational("2.1"),Rational("3.4"),Rational("2.9"),3]\nassert [x<=3 for x in d]==[True,False,True,True]',figure='dis-11'),
E('Le trésor',r'Sur ce plan, 1 cm représente 1 m. Un trésor est enterré à 4 m du pin P et à 3 m du rocher R, qui sont distants de 5 m. Où peut-il se trouver ?',r'Le trésor est sur le cercle de centre P de rayon 4 cm et sur le cercle de centre R de rayon 3 cm. Les cercles se coupent en $\res2$ points, $T_1$ et $T_2$ : il faut creuser à l’un de ces deux endroits.','Traduire chaque distance par un cercle.','assert 4-3<5<4+3',figure='dis-12'),
E('La chèvre',r'Une chèvre est attachée au piquet O par une corde de 5 m. Sur le plan, 1 cm représente 2 m. Les fleurs sont à 4 m (F1), $5{,}5$ m (F2) et 5 m (F3) du piquet. Lesquelles peut-elle brouter ?',r'Elle atteint tous les points du disque de centre O et de rayon 5 m. Elle broute $\res{\text{F1 et F3}}$ ; F2, à $5{,}5$ m, est hors de portée.','La zone accessible est un disque.','assert 4<=5 and 5<=5 and Rational("5.5")>5',figure='dis-13'),
E('Deux cercles qui se touchent',r'Les cercles de centres A et B ont le même rayon, 3 cm, et $AB=6$ cm. Ils se touchent en un seul point M, situé sur le segment [AB]. Expliquer pourquoi M est le milieu de [AB].',r'M est sur le cercle de centre A, donc $AM=3$ cm ; il est sur le cercle de centre B, donc $BM=3$ cm. M est sur le segment [AB] et $AM=MB$ : M est le $\res{\text{milieu de [AB]}}$.','Traduire « être sur un cercle » par une distance.','assert 3+3==6',figure='dis-14'),
E('Vrai ou faux',r'Yanis affirme : « Si $MA=MB$, alors M est le milieu du segment [AB]. » Le point M de la figure vérifie $MA=MB=3$ cm et $AB=4$ cm. Yanis a-t-il raison ?',r'$\res{\text{Non}}$ : M est à égale distance de A et de B, mais il n’est pas sur le segment [AB]. Le milieu I de [AB] vérifie $IA=IB=2$ cm. Pour être le milieu, il faut aussi appartenir au segment.','Vérifier les deux conditions de la définition.','assert 3+3>4 and 4/2==2',figure='dis-15')
],reperes=['Vocabulaire, notations et codages','Distance et milieu','Cercle, disque, rayon, diamètre et corde','Problèmes de distances'],deco='geometrie')

chapitre(14,'mediatrice','Médiatrice et équidistance','3 · Espace et géométrie',
'Perpendiculaire · Milieu · Points équidistants',
['Connaître la définition de la médiatrice d’un segment et la construire.','Utiliser la propriété caractéristique dans les deux sens.','Résoudre des problèmes de points à égale distance.'],
['Milieu d’un segment ; perpendiculaires ; compas.'],[
page(1,'Définir une médiatrice',
bloc('definition',r'La médiatrice d’un segment est la droite perpendiculaire à ce segment qui passe par son milieu.'),
r'@FIG:cours-mediatrice@',
sec(2,'Construire avec les instruments'),
bloc('savoirfaire',r'On place le milieu I du segment [AB], puis on trace la droite perpendiculaire au segment passant par I.','À la règle et à l’équerre'),
bloc('savoirfaire',r'Avec un même écartement, plus grand que la moitié de AB, on trace un arc de centre A et un arc de centre B, au-dessus puis au-dessous du segment. Les deux points d’intersection des arcs sont sur la médiatrice : on trace la droite qui les joint.','Au compas')),
page(3,'Deux sens d’une caractérisation',
bloc('propriete',r'Si un point appartient à la médiatrice d’un segment [AB], alors il est à égale distance de A et de B. Réciproquement, si un point est à égale distance de A et de B, alors il appartient à la médiatrice de [AB].'),
r'@FIG:cours-equidistance@',
bloc('exemple',r'Sur la figure, M est sur la médiatrice de [AB] et $MA=4$ cm : on peut affirmer, sans mesurer, que $MB=4$ cm. En revanche $NA\ne NB$ : N n’est pas sur la médiatrice.'),
sec(4,'Raisonner avec des lieux de points'),
bloc('savoirfaire',r'Je sais que $PA=PB=5$ cm (donnée). Or un point à égale distance de A et de B est sur la médiatrice de [AB] (propriété). Donc P est sur la médiatrice de [AB] (conclusion).','Rédiger en trois temps'),
bloc('attention',r'Une impression visuelle ne suffit pas : des longueurs qui « semblent » égales doivent être données, mesurées ou justifiées.')),
],[
E('Reconnaître la médiatrice',r'Le segment [AB] mesure 6 cm. Parmi les droites $(d_1)$, $(d_2)$, $(d_3)$ et $(d_4)$, laquelle est la médiatrice de [AB] ? Justifier en éliminant les autres.',r'$(d_1)$ est perpendiculaire mais ne passe pas par le milieu ; $(d_2)$ passe par le milieu mais n’est pas perpendiculaire ; $(d_4)$ ne vérifie aucune condition. La médiatrice est $\res{(d_3)}$ : perpendiculaire en son milieu.','Vérifier les deux conditions de la définition.','assert 6/2==3',figure='med-1'),
E('Coder une médiatrice',r'La droite (d) est la médiatrice du segment [AB]. Reproduire la figure et ajouter tous les codages utiles.',r'On code les deux moitiés de [AB] par un même signe et l’angle droit entre (d) et (AB) par un petit carré, en vert.','Coder le milieu et l’angle droit.','assert 1+1==2',figure='med-2'),
E('Construire à l’équerre',r'Tracer un segment [AB] de 6 cm, puis sa médiatrice à la règle graduée et à l’équerre.',r'On place le milieu I avec $AI=3$ cm, puis on trace la perpendiculaire à (AB) passant par I : c’est la médiatrice, en vert.','Milieu d’abord, perpendiculaire ensuite.','assert 6/2==3',figure='med-3'),
E('Une longueur sans mesurer',r'Le point M est sur la médiatrice du segment [AB] et $MA=4{,}2$ cm. Que vaut MB ? Justifier.',r'M est sur la médiatrice de [AB], donc il est à égale distance de A et de B : $\res{MB=4{,}2\ \mathrm{cm}}$.','Utiliser la propriété dans le sens direct.','assert Rational("4.2")==Rational("4.2")',figure='med-4'),
E('Sur la médiatrice ?',r'On sait que $PA=PB=3{,}5$ cm, que $QA=3$ cm et que $QB=4$ cm. Lesquels des points P et Q sont sur la médiatrice de [AB] ?',r'P est à égale distance de A et de B : il est $\res{\text{sur la médiatrice}}$. Comme $QA\ne QB$, Q n’est $\res{\text{pas sur la médiatrice}}$.','Utiliser la propriété réciproque.','assert 3!=4',figure='med-5'),
E('Construire au compas',r'Tracer un segment [CD] de 5 cm. Construire sa médiatrice au compas, avec un écartement de 4 cm.',r'Les arcs de rayon 4 cm, de centres C et D, se coupent en deux points E et F, à 4 cm de C et de D. La droite (EF) est la médiatrice de [CD], en vert.','L’écartement doit dépasser la moitié de CD.','assert 4>5/2',figure='med-6'),
E('Le triangle isocèle',r'Le triangle ABC vérifie $AB=AC=5$ cm et $BC=6$ cm. Démontrer que A est sur la médiatrice de [BC]. Où cette médiatrice coupe-t-elle le segment [BC] ?',r'Je sais que $AB=AC$. Or un point à égale distance de B et de C est sur la médiatrice de [BC]. Donc $\res{\text{A est sur la médiatrice de [BC]}}$. Elle coupe [BC] en son milieu, à 3 cm de B.','Rédiger avec la propriété réciproque.','assert 6/2==3',figure='med-7'),
E('Le losange',r'ABCD est un losange : ses quatre côtés ont la même longueur. Démontrer que la droite (BD) est la médiatrice du segment [AC].',r'$BA=BC$, donc B est sur la médiatrice de [AC]. $DA=DC$, donc D est aussi sur cette médiatrice. Une droite est déterminée par deux de ses points : la médiatrice de [AC] est $\res{\text{la droite (BD)}}$.','Trouver deux points de la médiatrice.','assert 4==4',figure='med-8'),
E('Un point sur une droite',r'Construire le point M de la droite (d) qui est à égale distance de A et de B.',r'M est à égale distance de A et de B, donc il est sur la médiatrice de [AB]. On trace cette médiatrice : elle coupe (d) au point M cherché, en vert.','Remplacer la condition de distance par une droite.','assert True',figure='med-9'),
E('Des cercles passant par A et B',r'Les points A et B sont distants de 4 cm. Où sont situés les centres des cercles qui passent à la fois par A et par B ? En tracer deux.',r'Le centre O d’un tel cercle vérifie $OA=OB$ (deux rayons) : il est sur la $\res{\text{médiatrice de [AB]}}$. Deux exemples sont tracés en vert, de centres $O_1$ et $O_2$.','Un cercle passant par A et B a deux rayons égaux, OA et OB.','assert True',figure='med-10'),
E('L’arrêt de bus',r'Les maisons A et B sont situées de part et d’autre d’une route droite (d). On veut placer un arrêt de bus S sur la route, à la même distance des deux maisons. Construire S.',r'S doit vérifier $SA=SB$ : il est sur la médiatrice de [AB]. Le point S cherché est l’intersection de cette médiatrice et de la route, en vert.','Traduire l’équidistance par la médiatrice.','assert True',figure='med-11'),
E('Plus près de A ou de B ?',r'Colorier la zone des points plus proches de A que de B. Quelle ligne sépare les deux zones ?',r'La frontière est formée des points à égale distance de A et de B : c’est la $\res{\text{médiatrice de [AB]}}$. Les points plus proches de A sont du côté de A, colorés en vert.','La médiatrice partage le plan en deux zones.','assert True',figure='med-12'),
E('Le pliage',r'On plie une feuille de façon que le point A vienne exactement sur le point B. Expliquer pourquoi le pli est la médiatrice du segment [AB].',r'Chaque point du pli est à la même distance de A et de B, puisque le pliage superpose A et B. Le pli est donc formé de points équidistants de A et de B : c’est la $\res{\text{médiatrice de [AB]}}$, en vert.','Relier pliage et équidistance.','assert True',figure='med-13'),
E('Raisonner',r'La droite (d) est la médiatrice de [AB]. Le point C est sur (d) et $CA=5$ cm. Le point D vérifie $DA=DB=3{,}5$ cm. Que vaut CB ? Le point D est-il sur (d) ? Rédiger les deux réponses.',r'C est sur la médiatrice, donc $\res{CB=CA=5\ \mathrm{cm}}$. D est à égale distance de A et de B, donc $\res{\text{D est sur (d)}}$. La première réponse utilise la propriété, la seconde sa réciproque.','Choisir le bon sens de la propriété.','assert 5==5',figure='med-14'),
E('Vrai ou faux',r'Léo affirme : « Un point à égale distance de A et de B est toujours le milieu de [AB]. » A-t-il raison ?',r'$\res{\text{Non}}$ : tous les points de la médiatrice sont à égale distance de A et de B, comme le point M de la figure. Un seul d’entre eux est sur le segment [AB] : son milieu I.','Penser à tous les points de la médiatrice.','assert True',figure='med-15')
],reperes=['Définition et codage de la médiatrice','Constructions à l’équerre et au compas','Propriété caractéristique dans les deux sens','Problèmes de points équidistants'],deco='geometrie')

chapitre(15,'angles','Angles et bissectrices','3 · Espace et géométrie',
'Vocabulaire · Rapporteur · Angles associés · Bissectrice',
['Nommer, mesurer et construire un angle au rapporteur.','Utiliser angles adjacents, opposés par le sommet et supplémentaires.','Définir et construire la bissectrice d’un angle.'],
['Demi-droites ; angle droit ; lecture d’une graduation.'],[
page(1,'Nommer et reconnaître les angles',
bloc('definition',r'Un angle est formé de deux demi-droites de même origine : ses côtés. Cette origine est son sommet. L’angle formé par les demi-droites [OA) et [OB) se note $\widehat{AOB}$ : la lettre du sommet est au milieu. Les angles se mesurent en degrés.'),
bloc('definition',r'Un angle est nul s’il mesure $0^\circ$ ; aigu s’il mesure entre $0^\circ$ et $90^\circ$ ; droit s’il mesure $90^\circ$ ; obtus entre $90^\circ$ et $180^\circ$ ; plat s’il mesure $180^\circ$ ; plein s’il mesure $360^\circ$.'),
sec(2,'Mesurer et construire au rapporteur'),
bloc('savoirfaire',r'On place le centre du rapporteur sur le sommet et une graduation 0 sur un côté. On lit la mesure à l’endroit où passe le second côté, sur la graduation qui part de 0.','Mesurer un angle'),
r'@FIG:cours-rapporteur@',
bloc('savoirfaire',r'Pour construire un angle $\widehat{xAy}$ de $65^\circ$ : tracer [Ax), placer le centre du rapporteur en A et le 0 sur [Ax), marquer un point en face de 65, puis tracer la demi-droite [Ay).','Construire un angle')),
page(3,'Angles adjacents, opposés et supplémentaires',
bloc('definition',r'Deux angles adjacents ont le même sommet et un côté commun, et sont situés de part et d’autre de ce côté. Deux angles sont supplémentaires si la somme de leurs mesures vaut $180^\circ$.'),
bloc('propriete',r'Quand deux droites se coupent, deux angles opposés par le sommet ont la même mesure. Deux angles adjacents qui forment un angle plat sont supplémentaires.'),
r'@FIG:cours-paires-bissectrice@',
sec(4,'Définir et construire une bissectrice'),
bloc('definition',r'La bissectrice d’un angle saillant, c’est-à-dire de mesure inférieure à $180^\circ$, est la demi-droite issue du sommet qui partage cet angle en deux angles adjacents de même mesure.'),
bloc('savoirfaire',r'Un arc de centre O coupe les côtés en M et N. Deux arcs de même rayon, de centres M et N, se coupent en P. La demi-droite [OP) est la bissectrice. Au rapporteur, on marque simplement la moitié de la mesure.','Au compas')),
],[
E('Nommer un angle',r'Nommer l’angle marqué en vert, puis donner son sommet et ses côtés.',r'L’angle se note $\widehat{AOB}$, ou $\widehat{BOA}$. Son sommet est $\res O$ ; ses côtés sont les demi-droites $\res{\text{[OA) et [OB)}}$.','Le sommet s’écrit au milieu.','assert True',figure='ang-1'),
E('Aigu, droit, obtus…',r'Pour chacun des angles a, b, c, d et e, dire s’il est aigu, droit, obtus ou plat.',r'a : $\res{\text{aigu}}$ ; b : $\res{\text{droit}}$ ; c : $\res{\text{obtus}}$ ; d : $\res{\text{plat}}$ ; e : $\res{\text{aigu}}$.','Comparer chaque angle à un angle droit.','m=[25,90,130,180,70]\nassert m[0]<90 and m[1]==90 and 90<m[2]<180 and m[3]==180 and m[4]<90',figure='ang-2'),
E('Lire le rapporteur',r'Lire la mesure de l’angle $\widehat{AOB}$.',r'Le côté [OA) passe par le 0 de la graduation extérieure. On lit sur cette graduation : $\res{70^\circ}$. L’angle est aigu, ce qui confirme la lecture.','Suivre la graduation qui part de 0.','assert 0<70<90',figure='ang-3'),
E('Avec l’autre graduation',r'Lire la mesure de l’angle $\widehat{COD}$.',r'Le côté [OC) passe par le 0 de la graduation intérieure. On lit sur celle-ci : $\res{125^\circ}$, et non 55 : l’angle est obtus.','Contrôler : aigu ou obtus ?','assert 180-125==55 and 90<125<180',figure='ang-4'),
E('Estimer',r'Sans rapporteur, associer chacun des angles a, b et c à l’une des mesures $45^\circ$, $100^\circ$ et $160^\circ$.',r'a est un peu plus grand qu’un angle droit : $\res{100^\circ}$. b est la moitié d’un angle droit : $\res{45^\circ}$. c est presque plat : $\res{160^\circ}$.','Comparer à l’angle droit et à l’angle plat.','assert 45<90<100<160<180',figure='ang-5'),
E('Construire un angle',r'Reproduire la demi-droite [Ax), puis construire la demi-droite [Ay) telle que $\widehat{xAy}=65^\circ$.',r'Centre du rapporteur en A, 0 sur [Ax) ; on marque 65 et on trace [Ay), en vert. L’angle obtenu est aigu, comme prévu.','Placer le 0 sur le côté donné.','assert 0<65<90',figure='ang-6'),
E('Adjacents ou non ?',r'Dans chacune des trois figures, les deux angles marqués sont-ils adjacents ? Justifier.',r'Figure 1 : $\res{\text{oui}}$, même sommet, côté commun, de part et d’autre. Figure 2 : $\res{\text{non}}$, l’un est à l’intérieur de l’autre. Figure 3 : $\res{\text{non}}$, les sommets sont différents.','Vérifier les trois conditions.','assert True',figure='ang-7'),
E('Supplémentaires',r'Les points A, O et B sont alignés. L’angle $\widehat{AOC}$ mesure $128^\circ$. Calculer la mesure de l’angle $\widehat{COB}$.',r'$\widehat{AOB}$ est plat : les deux angles sont supplémentaires. $180-128=\res{52^\circ}$.','Compléter à 180 degrés.','assert 180-128==52',figure='ang-8'),
E('Opposés par le sommet',r'Deux droites se coupent en O. L’un des angles mesure $47^\circ$. Calculer les trois autres.',r'L’angle opposé mesure aussi $\res{47^\circ}$. Les deux autres lui sont supplémentaires : $180-47=\res{133^\circ}$ chacun. Contrôle : $47+133+47+133=360$.','Combiner angles opposés et supplémentaires.','assert 180-47==133 and 2*(47+133)==360',figure='ang-9'),
E('La bissectrice au rapporteur',r'L’angle $\widehat{xOy}$ mesure $84^\circ$. Construire sa bissectrice au rapporteur et donner la mesure des deux angles obtenus.',r'$84:2=\res{42^\circ}$. On marque 42 à partir de [Ox) et on trace la bissectrice, en vert.','Diviser la mesure par deux.','assert 84/2==42',figure='ang-10'),
E('Autour d’un point',r'Quatre angles adjacents font le tour du point O. Trois d’entre eux mesurent $110^\circ$, $95^\circ$ et $80^\circ$. Calculer la mesure du quatrième.',r'Un tour complet mesure $360^\circ$ : $360-110-95-80=\res{75^\circ}$.','Utiliser l’angle plein.','assert 360-110-95-80==75',figure='ang-11'),
E('Les aiguilles',r'Le cadran d’une horloge est partagé en 12 heures. Quel angle forment les deux aiguilles à 3 h ? À 4 h, comme sur le dessin ? À 5 h ?',r'Une heure correspond à $360:12=30^\circ$. À 3 h : $\res{90^\circ}$ ; à 4 h : $\res{120^\circ}$ ; à 5 h : $\res{150^\circ}$.','Compter des écarts de 30 degrés.','assert 360/12==30 and 3*30==90 and 4*30==120 and 5*30==150',figure='ang-12'),
E('La bissectrice au compas',r'Reproduire l’angle $\widehat{xOy}$ de $70^\circ$, puis construire sa bissectrice au compas, sans rapporteur. Quelle est la mesure de chaque moitié ?',r'Arc de centre O, puis deux arcs de même rayon centrés sur les côtés : ils se coupent en P et [OP) est la bissectrice, en vert. Chaque moitié mesure $70:2=\res{35^\circ}$.','Suivre les trois étapes de la construction.','assert 70/2==35',figure='ang-13'),
E('Deux bissectrices',r'Les points A, O et B sont alignés et $\widehat{AOC}=130^\circ$. On trace les bissectrices des angles $\widehat{AOC}$ et $\widehat{COB}$. Quel angle forment-elles ?',r'$\widehat{COB}=180-130=50^\circ$. Les moitiés mesurent $65^\circ$ et $25^\circ$. Les deux bissectrices forment un angle de $65+25=\res{90^\circ}$ : elles sont perpendiculaires.','Additionner les deux moitiés.','assert (180-130)==50 and 130/2+50/2==90',figure='ang-14'),
E('Vrai ou faux',r'Inès affirme : « L’angle a est plus grand que l’angle b, car ses côtés sont plus longs. » A-t-elle raison ?',r'$\res{\text{Non}}$ : la longueur des côtés ne compte pas, seule l’ouverture compte. Au rapporteur, a mesure $40^\circ$ et b mesure $60^\circ$ : $\res{\text{b est plus grand}}$.','Mesurer l’ouverture, pas les côtés.','assert 40<60',figure='ang-15')
],reperes=['Vocabulaire et types d’angles','Mesurer et construire au rapporteur','Angles adjacents, opposés et supplémentaires','Bissectrice et problèmes'],deco='geometrie')
